import {clone,div} from './model.js';
/** Reserve-backed synthetic project receipts. CCLX is the reserve unit, not a project equity share. */
export const curveIntegral=(a,b,s)=>a*s+b*s*s/2;
export const curveSpot=(a,b,s)=>a+b*s;
export function sharesForReserve(a,b,reserve){if(a<=0||b<0||reserve<0)throw Error('Invalid curve parameters.');return b===0?reserve/a:2*reserve/(Math.sqrt(a*a+2*b*reserve)+a);}
export function newVault(p){const shares=sharesForReserve(p.curveA,p.curveB,p.collateral);return {projectId:p.id,backing:p.collateral,shares,fees:0,feeAccounts:{CCLX:{curve_user_gross:0,treasury_pending:0}},initialOwners:{[`initial-${p.id}`]:shares},a:p.curveA,b:p.curveB,fee:p.curveFee,capacity:p.capacity};}
export function curveQuote(v,amount,side='deposit'){if(!Number.isFinite(amount)||amount<0)throw Error('Invalid curve amount.');if(side==='deposit'){const net=amount*(1-v.fee);if(v.backing+net>v.capacity+1e-8)throw Error('Project collateral capacity exceeded.');const shares=sharesForReserve(v.a,v.b,v.backing+net)-v.shares,avg=div(net,shares),spotBefore=curveSpot(v.a,v.b,v.shares),spotAfter=curveSpot(v.a,v.b,v.shares+shares);return {input:amount,shares,backingDelta:net,fee:amount-net,spotBefore,spotAfter,averagePrice:avg,averageSlippage:div(avg,spotBefore)-1,marginalMove:div(spotAfter,spotBefore)-1,totalUserCost:div(amount,shares)};}
if(side==='withdraw'){if(amount>v.shares+1e-8)throw Error('Insufficient receipt shares.');const target=Math.max(0,v.shares-amount),gross=v.backing-curveIntegral(v.a,v.b,target),avg=div(gross,amount),spotBefore=curveSpot(v.a,v.b,v.shares),spotAfter=curveSpot(v.a,v.b,target);return {input:amount,shares:amount,backingDelta:-gross,output:gross*(1-v.fee),fee:gross*v.fee,spotBefore,spotAfter,averagePrice:avg,averageSlippage:1-div(avg,spotBefore),marginalMove:div(spotAfter,spotBefore)-1,totalUserCost:div(gross*v.fee,Math.max(1e-12,gross))};}
throw Error('Unknown curve side.');}
export function curveTrade(v,amount,side){const out=curveQuote(v,amount,side);if(side==='deposit'){v.shares+=out.shares;v.backing+=out.backingDelta;}else{v.shares-=out.shares;v.backing+=out.backingDelta;}v.fees+=out.fee;if(v.feeAccounts?.CCLX){v.feeAccounts.CCLX.curve_user_gross+=out.fee;v.feeAccounts.CCLX.treasury_pending+=out.fee;}if(v.backing<0||v.shares<0)throw Error('Curve insolvency.');return out;}
export const positionValue=(v,shares)=>shares>0&&v.shares>0?shares/v.shares*v.backing:0;
export function positionRedemptionQuote(v,shares){const q=curveQuote(v,shares,'withdraw');return {...q,proportionalValue:positionValue(v,shares),marginalValue:shares*curveSpot(v.a,v.b,v.shares)};}
export function sharesForWithdrawalOutput(v,output){if(!Number.isFinite(output)||output<0)throw Error('Invalid withdrawal output.');const full=curveQuote(v,v.shares,'withdraw').output;if(output>full+1e-8)throw Error('Withdrawal exceeds current executable redemption value.');const gross=output/(1-v.fee),targetBacking=Math.max(0,v.backing-gross),targetShares=sharesForReserve(v.a,v.b,targetBacking);return v.shares-targetShares;}
export function curveAudit(v){const expected=curveIntegral(v.a,v.b,v.shares);return {backing:v.backing,expected,residual:v.backing-expected,fees:v.fees,feeAccounts:v.feeAccounts,initialOwners:v.initialOwners,solvent:v.backing>=-1e-8&&Math.abs(v.backing-expected)<1e-5*Math.max(1,v.backing),spot:curveSpot(v.a,v.b,v.shares),fullyBackedRedemption:curveQuote(v,v.shares,'withdraw').output};}
/** Parameter changes require an explicit reserve transfer; a milestone alone never creates backing. */
export function rebaseCurve(v,a,b,topup=0){const next=clone(v);if(a<=0||b<0||topup<0)throw Error('Invalid rebase.');const required=curveIntegral(a,b,v.shares)-v.backing;if(required>topup+1e-8)throw Error('Unfunded curve rebase.');next.a=a;next.b=b;next.backing+=required;return {vault:next,requiredTopup:Math.max(0,required),releasedReserve:Math.max(0,-required)};}
